import numpy as np

class TrieNode:
    def __init__(self):
        self.children = np.full(26, None)
        self.isEnd = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        curr = self.root
        for c in word:
            idx = c - ord('a')
            if curr.children[idx] is None:
                curr.children[idx] = TrieNode()
            curr = curr.children[idx]
        curr.isEnd = True

    def search(self, word):
        curr = self.root
        for c in word:
            idx = c - ord('a')
            if curr.children[idx] is None:
                return False
            curr = curr.children[idx]
        return curr.isEnd

    def startsWith(self, prefix):
        curr = self.root
        for c in prefix:
            idx = c - ord('a')
            if curr.children[idx] is None:
                return False
            curr = curr.children[idx]
        return True

def main():
