     string result =  "" ;
     // Variable to store the first letter
     string first_letter =  "" ;
     // To check if the first word is palindrome
     // or not
     bool isPalindrome =  false ;
     // If the first letter of the first word
     // is equal to the last letter of the first
     // word, then it is a palindrome
