#include <string>
#include <vector>
#include <unordered_map>
#include <algorithm>

using namespace std;

int countPalindromes(const string &s) {
    int n = s.length();
    vector<int> count(128, 0);
    for (const char &c : s) {
        count[c]++;
    }
    int res = 0;
    for (int i = 0; i < 128; i++) {
        if (count[i] % 2 == 1) {
            res++;
        }
    }
    return res;
}

int maxPalindromes(const string &s) {
    int n = s.length();
    int res = 0;
    int i = 0, j = 0;
    int index = 0;
    while (i < n && j < n) {
        if (index < countPalindromes(s)) {
            res++;
            index++;
        }
        if (s[i] == s[j]) {
            i++;
            j++;
        }
        else {
            i++;
        }
    }
    return res;
}
